const config: runtime.GetPrismaClientConfig = {
  "previewFeatures": [],
  "clientVersion": "7.9.1",
  "engineVersion": "e922089b7d7502aff4249d5da3420f6fa55fc6ad",
  "activeProvider": "postgresql",
  "inlineSchema": "// ---------------------------------------------------------------------------\n// Weber Store - esquema de base de datos\n//\n// Organizado en cuatro bloques, en este orden:\n//   1. Catalogos    tablas de valores reutilizables que alimentan los dropdowns\n//   2. Producto     el catalogo comercial\n//   3. Contenido    secciones editables del sitio (Grill Academy, B2B, etc.)\n//   4. Operacion    prospectos y configuracion del sitio\n//\n// Carrito, ordenes y usuarios llegan despues. Nada de lo que hay aqui los\n// bloquea: Product ya tiene precio y stock, y los prospectos ya viven aparte.\n// ---------------------------------------------------------------------------\n\n// Prisma 7 retira \"prisma-client-js\" y exige decir donde escribir el cliente.\n// Antes aterrizaba dentro de node_modules, invisible para todos; ahora es una\n// carpeta del paquete, ignorada por git y declarable como salida de turbo.\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\n// Las URLs ya no viven aqui: Prisma 7 las lee de prisma.config.ts para el CLI\n// y del adaptador para el cliente. El esquema solo declara el motor.\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ===========================================================================\n// 1. CATALOGOS\n//\n// Todos siguen la misma forma a proposito: slug estable para las URLs, name\n// para mostrar, position para el orden en el dropdown y active para ocultar\n// una opcion sin borrarla. El admin los edita como tablas simples.\n// ===========================================================================\n\n/// Marca. Hoy solo Weber, pero el catalogo permite crecer sin migracion.\nmodel Brand {\n  id        String    @id @default(cuid())\n  slug      String    @unique\n  name      String\n  logoUrl   String?\n  position  Int       @default(0)\n  active    Boolean   @default(true)\n  products  Product[]\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  @@map(\"marcas\")\n}\n\n/// Que es el producto: Asador, Ahumador, Plancha, Accesorio, Combustible...\nmodel ProductType {\n  id        String    @id @default(cuid())\n  slug      String    @unique\n  name      String\n  position  Int       @default(0)\n  active    Boolean   @default(true)\n  products  Product[]\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  @@map(\"tipos_producto\")\n}\n\n/// Con que funciona: Carbon, Gas, Electrico, Pellet.\n/// Los accesorios no llevan combustible, por eso la relacion es opcional.\nmodel FuelType {\n  id        String    @id @default(cuid())\n  slug      String    @unique\n  name      String\n  icon      String?\n  position  Int       @default(0)\n  active    Boolean   @default(true)\n  products  Product[]\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  @@map(\"combustibles\")\n}\n\n/// Linea de producto: Spirit, Genesis, Summit, Q, Traveler, Master-Touch...\n/// Es la dimension que mas usan los clientes para buscar accesorios.\nmodel Series {\n  id           String                 @id @default(cuid())\n  slug         String                 @unique\n  name         String\n  description  String?\n  imageUrl     String?\n  position     Int                    @default(0)\n  active       Boolean                @default(true)\n  products     Product[]\n  /// Accesorios que declaran ser compatibles con esta serie.\n  compatibleTo ProductCompatibility[]\n  createdAt    DateTime               @default(now())\n  updatedAt    DateTime               @updatedAt\n\n  @@map(\"series\")\n}\n\n/// Como se instala o transporta: Portatil, Empotrable, De carro, De mesa.\nmodel Format {\n  id        String    @id @default(cuid())\n  slug      String    @unique\n  name      String\n  position  Int       @default(0)\n  active    Boolean   @default(true)\n  products  Product[]\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  @@map(\"formatos\")\n}\n\n/// Color del producto. hex sirve para pintar el selector en la ficha.\nmodel Color {\n  id        String    @id @default(cuid())\n  slug      String    @unique\n  name      String\n  hex       String?\n  position  Int       @default(0)\n  active    Boolean   @default(true)\n  products  Product[]\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  @@map(\"colores\")\n}\n\n/// Medida del asador: 14\", 18\", 22\", 26\", 37.5\".\n/// inches se guarda aparte para poder ordenar y filtrar por rango.\nmodel SizeOption {\n  id        String    @id @default(cuid())\n  slug      String    @unique\n  name      String\n  inches    Decimal?  @db.Decimal(5, 2)\n  position  Int       @default(0)\n  active    Boolean   @default(true)\n  products  Product[]\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  @@map(\"tamanos\")\n}\n\n/// Categoria de navegacion, jerarquica. Es lo que ve el cliente en el menu:\n/// Gas, Carbon, Electricos, Planchas, Portatiles, Empotrables, Accesorios.\nmodel Category {\n  id              String            @id @default(cuid())\n  slug            String            @unique\n  name            String\n  description     String?\n  imageUrl        String?\n  parentId        String?\n  parent          Category?         @relation(\"CategoryTree\", fields: [parentId], references: [id], onDelete: SetNull)\n  children        Category[]        @relation(\"CategoryTree\")\n  products        ProductCategory[]\n  menuItems       MenuItem[]\n  metaTitle       String?\n  metaDescription String?\n  position        Int               @default(0)\n  active          Boolean           @default(true)\n  createdAt       DateTime          @default(now())\n  updatedAt       DateTime          @updatedAt\n\n  @@index([parentId])\n  @@map(\"categorias\")\n}\n\n/// Agrupacion curada a mano, no derivada de los atributos del producto:\n/// \"Mas Vendidos\", \"Ofertas de Temporada\", \"Novedades\".\n/// startsAt/endsAt dejan que una promocion aparezca y desaparezca sola,\n/// que es justo lo que pide el Excel para las ofertas de Weber.\nmodel Collection {\n  id              String              @id @default(cuid())\n  slug            String              @unique\n  name            String\n  description     String?\n  imageUrl        String?\n  kind            CollectionKind      @default(CURATED)\n  startsAt        DateTime?\n  endsAt          DateTime?\n  products        ProductCollection[]\n  metaTitle       String?\n  metaDescription String?\n  position        Int                 @default(0)\n  active          Boolean             @default(true)\n  createdAt       DateTime            @default(now())\n  updatedAt       DateTime            @updatedAt\n\n  @@map(\"colecciones\")\n}\n\nenum CollectionKind {\n  CURATED /// seleccion manual, ej. Mas Vendidos\n  PROMO /// campaña con vigencia, ej. Ofertas de Temporada\n}\n\n// ===========================================================================\n// 2. PRODUCTO\n// ===========================================================================\n\nenum ProductStatus {\n  DRAFT /// importado pero sin revisar: no se muestra en la tienda\n  ACTIVE /// publicado\n  ARCHIVED /// oculto por decision propia\n  DISCONTINUED /// Weber ya no lo fabrica\n}\n\nmodel Product {\n  id   String @id @default(cuid())\n  /// SKU de Weber. Es la llave con la que se cruzan las listas de precios.\n  sku  String @unique\n  slug String @unique\n  name String\n\n  shortDescription String?\n  description      String?\n\n  status ProductStatus @default(DRAFT)\n\n  /// Primera vez que el producto se publico. Marca el momento en que su URL\n  /// dejo de ser libre: a partir de aqui puede haber enlaces apuntando a ella\n  /// y buscadores que ya la indexaron, asi que cambiarla tiene consecuencias.\n  /// Nulo mientras nunca haya salido a la tienda.\n  publishedAt DateTime?\n\n  // --- Comercial ---------------------------------------------------------\n  /// Precio de venta. Nulo mientras no se capture la lista de precios.\n  price          Decimal? @db.Decimal(10, 2)\n  /// Precio de lista, el que se muestra tachado en una oferta.\n  compareAtPrice Decimal? @db.Decimal(10, 2)\n  /// Costo interno. Nunca se expone en la tienda publica.\n  cost           Decimal? @db.Decimal(10, 2)\n  currency       String   @default(\"MXN\")\n\n  // --- Inventario --------------------------------------------------------\n  stock          Int     @default(0)\n  trackStock     Boolean @default(true)\n  allowBackorder Boolean @default(false)\n\n  // --- Atributos (todos dropdowns alimentados por los catalogos) ---------\n  brandId       String?\n  brand         Brand?       @relation(fields: [brandId], references: [id], onDelete: SetNull)\n  productTypeId String?\n  productType   ProductType? @relation(fields: [productTypeId], references: [id], onDelete: SetNull)\n  fuelTypeId    String?\n  fuelType      FuelType?    @relation(fields: [fuelTypeId], references: [id], onDelete: SetNull)\n  seriesId      String?\n  series        Series?      @relation(fields: [seriesId], references: [id], onDelete: SetNull)\n  formatId      String?\n  format        Format?      @relation(fields: [formatId], references: [id], onDelete: SetNull)\n  colorId       String?\n  color         Color?       @relation(fields: [colorId], references: [id], onDelete: SetNull)\n  sizeId        String?\n  size          SizeOption?  @relation(fields: [sizeId], references: [id], onDelete: SetNull)\n\n  categories    ProductCategory[]\n  collections   ProductCollection[]\n  images        ProductImage[]\n  specs         ProductSpec[]\n  /// Para accesorios: con que series es compatible.\n  compatibility ProductCompatibility[]\n\n  // --- SEO ---------------------------------------------------------------\n  metaTitle       String?\n  metaDescription String?\n\n  // --- Trazabilidad de la importacion ------------------------------------\n  /// Texto original de las columnas del Excel, para poder auditar la\n  /// normalizacion sin volver a abrir el archivo.\n  rawCategory    String?\n  rawSubcategory String?\n  needsReview    Boolean @default(false)\n  reviewNote     String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status])\n  @@index([seriesId])\n  @@index([fuelTypeId])\n  @@index([productTypeId])\n  @@map(\"productos\")\n}\n\n/// Un producto vive en varias categorias. isPrimary define cual manda para\n/// la URL canonica y las migas de pan, lo que evita contenido duplicado.\nmodel ProductCategory {\n  productId  String\n  product    Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  categoryId String\n  category   Category @relation(fields: [categoryId], references: [id], onDelete: Cascade)\n  isPrimary  Boolean  @default(false)\n  position   Int      @default(0)\n\n  @@id([productId, categoryId])\n  @@index([categoryId])\n  @@map(\"producto_categoria\")\n}\n\nmodel ProductCollection {\n  productId    String\n  product      Product    @relation(fields: [productId], references: [id], onDelete: Cascade)\n  collectionId String\n  collection   Collection @relation(fields: [collectionId], references: [id], onDelete: Cascade)\n  position     Int        @default(0)\n\n  @@id([productId, collectionId])\n  @@index([collectionId])\n  @@map(\"producto_coleccion\")\n}\n\n/// \"Este accesorio sirve para Spirit\". Lo que hace posible el bloque\n/// \"compatible con tu asador\" en la ficha de producto.\nmodel ProductCompatibility {\n  productId String\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  seriesId  String\n  series    Series  @relation(fields: [seriesId], references: [id], onDelete: Cascade)\n  note      String?\n\n  @@id([productId, seriesId])\n  @@index([seriesId])\n  @@map(\"producto_compatibilidad\")\n}\n\nmodel ProductImage {\n  id        String  @id @default(cuid())\n  productId String\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  url       String\n  alt       String?\n  width     Int?\n  height    Int?\n  position  Int     @default(0)\n  isPrimary Boolean @default(false)\n  /// Ruta en Vercel Blob, necesaria para poder borrar el archivo real.\n  blobPath  String?\n\n  @@index([productId])\n  @@map(\"producto_imagenes\")\n}\n\n/// Ficha tecnica: \"Superficie de coccion\" / \"1,240 cm2\".\n/// Clave-valor libre para no migrar el esquema cada vez que Weber\n/// agrega una especificacion nueva.\nmodel ProductSpec {\n  id        String  @id @default(cuid())\n  productId String\n  product   Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  label     String\n  value     String\n  group     String?\n  position  Int     @default(0)\n\n  @@index([productId])\n  @@map(\"producto_especificaciones\")\n}\n\n// ===========================================================================\n// 3. CONTENIDO\n// ===========================================================================\n\n/// El menu principal se administra, no se programa. Asi puedes esconder\n/// \"Ofertas de Temporada\" cuando no hay promociones vigentes, tal como\n/// lo pide el Excel, sin tocar codigo ni desplegar.\nmodel MenuItem {\n  id         String       @id @default(cuid())\n  label      String\n  /// Destino directo. Se ignora si hay categoryId.\n  url        String?\n  categoryId String?\n  category   Category?    @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n  parentId   String?\n  parent     MenuItem?    @relation(\"MenuTree\", fields: [parentId], references: [id], onDelete: Cascade)\n  children   MenuItem[]   @relation(\"MenuTree\")\n  location   MenuLocation @default(HEADER)\n  highlight  Boolean      @default(false)\n  position   Int          @default(0)\n  active     Boolean      @default(true)\n  createdAt  DateTime     @default(now())\n  updatedAt  DateTime     @updatedAt\n\n  @@index([parentId])\n  @@map(\"menu\")\n}\n\nenum MenuLocation {\n  HEADER\n  FOOTER\n}\n\n/// Pagina de contenido editable: Ubicacion, Contacto, B2B - Mayoreo,\n/// Grill Academy, avisos legales. El cuerpo se arma con bloques.\nmodel Page {\n  id              String         @id @default(cuid())\n  slug            String         @unique\n  title           String\n  subtitle        String?\n  heroImageUrl    String?\n  blocks          ContentBlock[]\n  metaTitle       String?\n  metaDescription String?\n  published       Boolean        @default(false)\n  createdAt       DateTime       @default(now())\n  updatedAt       DateTime       @updatedAt\n\n  @@map(\"paginas\")\n}\n\n/// Bloque de una pagina. data guarda los campos propios de cada tipo,\n/// validados con Zod en @weber/core antes de escribir.\nmodel ContentBlock {\n  id       String    @id @default(cuid())\n  pageId   String\n  page     Page      @relation(fields: [pageId], references: [id], onDelete: Cascade)\n  type     BlockType\n  data     Json\n  position Int       @default(0)\n  active   Boolean   @default(true)\n\n  @@index([pageId])\n  @@map(\"bloques_contenido\")\n}\n\nenum BlockType {\n  RICH_TEXT\n  IMAGE\n  GALLERY\n  VIDEO\n  MAP\n  FILE_DOWNLOAD /// el PDF descargable de Grill Academy\n  FEATURE_LIST /// ventajas: espacio climatizado, pantallas 65\", estacionamiento\n  FAQ\n  CTA\n  CONTACT_FORM\n  PRODUCT_GRID\n}\n\n/// Curso de Grill Academy. Se lista en la seccion y alimenta las reservas.\nmodel Course {\n  id          String     @id @default(cuid())\n  slug        String     @unique\n  title       String\n  description String?\n  imageUrl    String?\n  startsAt    DateTime?\n  durationMin Int?\n  capacity    Int?\n  price       Decimal?   @db.Decimal(10, 2)\n  kind        CourseKind @default(PUBLIC)\n  published   Boolean    @default(false)\n  position    Int        @default(0)\n  createdAt   DateTime   @default(now())\n  updatedAt   DateTime   @updatedAt\n\n  @@map(\"cursos\")\n}\n\nenum CourseKind {\n  PUBLIC /// abierto al publico general\n  PRIVATE /// evento privado, se cotiza\n  CORPORATE /// evento corporativo, se cotiza\n}\n\n/// Galeria de fotos y videos, reutilizable entre secciones.\nmodel MediaAsset {\n  id        String    @id @default(cuid())\n  url       String\n  kind      MediaKind @default(IMAGE)\n  title     String?\n  alt       String?\n  /// Etiqueta libre para filtrar: \"grill-academy\", \"ubicacion\", \"eventos\".\n  tag       String?\n  width     Int?\n  height    Int?\n  blobPath  String?\n  position  Int       @default(0)\n  createdAt DateTime  @default(now())\n\n  @@index([tag])\n  @@map(\"media\")\n}\n\nenum MediaKind {\n  IMAGE\n  VIDEO\n  PDF\n}\n\n/// Banner de promocion: la imagen con el porcentaje de descuento que pide\n/// el Excel para Ofertas de Temporada. Con vigencia para que caduque solo.\nmodel Banner {\n  id             String     @id @default(cuid())\n  title          String\n  subtitle       String?\n  imageUrl       String\n  mobileImageUrl String?\n  linkUrl        String?\n  location       BannerSlot @default(HOME_HERO)\n  startsAt       DateTime?\n  endsAt         DateTime?\n  position       Int        @default(0)\n  active         Boolean    @default(true)\n  createdAt      DateTime   @default(now())\n  updatedAt      DateTime   @updatedAt\n\n  @@map(\"banners\")\n}\n\nenum BannerSlot {\n  HOME_HERO\n  HOME_STRIP\n  CATEGORY_TOP\n  PROMO_BAR /// la barra delgada de avisos arriba del header\n}\n\n// ===========================================================================\n// 4. OPERACION\n// ===========================================================================\n\n/// Prospecto entrante. Un solo modelo para los tres formularios del Excel\n/// (B2B, cotizacion de Grill Academy, contacto) diferenciados por kind.\nmodel Lead {\n  id        String     @id @default(cuid())\n  kind      LeadKind\n  name      String\n  email     String?\n  phone     String?\n  company   String?\n  message   String?\n  /// Campos extra propios del formulario, ej. numero de asistentes.\n  extra     Json?\n  status    LeadStatus @default(NEW)\n  /// De donde llego: pagina, campaña UTM.\n  source    String?\n  createdAt DateTime   @default(now())\n  updatedAt DateTime   @updatedAt\n\n  @@index([kind, status])\n  @@map(\"prospectos\")\n}\n\nenum LeadKind {\n  CONTACT\n  WHOLESALE /// B2B - Mayoreo\n  COURSE /// cotizacion o reserva de Grill Academy\n  PRODUCT /// pregunta sobre un producto\n}\n\nenum LeadStatus {\n  NEW\n  IN_PROGRESS\n  WON\n  LOST\n}\n\n/// Configuracion global del sitio, un solo registro (id = \"default\").\n/// Evita tener telefonos y horarios escritos a fuerza en el codigo.\nmodel SiteSetting {\n  id               String   @id @default(\"default\")\n  siteName         String   @default(\"Weber Store\")\n  whatsapp         String?\n  phone            String?\n  email            String?\n  addressLine      String?\n  city             String?\n  state            String?\n  postalCode       String?\n  googleMapsUrl    String?\n  googleMapsEmbed  String?\n  /// Horarios de atencion: [{ dia, abre, cierra }].\n  openingHours     Json?\n  facebookUrl      String?\n  instagramUrl     String?\n  youtubeUrl       String?\n  tiktokUrl        String?\n  /// Aviso de la barra superior, ej. \"Envio gratis en Monterrey\".\n  announcement     String?\n  /// Costo de entrega en area metropolitana de Monterrey.\n  localDeliveryFee Decimal? @db.Decimal(10, 2)\n  pickupEnabled    Boolean  @default(true)\n  updatedAt        DateTime @updatedAt\n\n  @@map(\"configuracion\")\n}\n",
  "runtimeDataModel": {
    "models": {},
    "enums": {},
    "types": {}
  },
  "parameterizationSchema": {
    "strings": [],
    "graph": ""
  }
}

